insert into category_three.question_bank (id, prompt, theme, answers, sort_order, version)
select r->>'id', r->>'prompt', r->>'theme', array(select jsonb_array_elements_text(r->'answers')), (r->>'sort_order')::int, r->>'version'
from jsonb_array_elements('[{"id":"funny-51","prompt":"What does a strong family need more than matching holiday photos?","theme":"Care, Family & Everyday Support","answers":["Care","Trust","Responsibility","Presence"],"sort_order":51,"version":"funny"},{"id":"funny-52","prompt":"What makes care feel like love instead of a transaction?","theme":"Care, Family & Everyday Support","answers":["Reciprocity","Affection","Patience","Reliability"],"sort_order":52,"version":"funny"},{"id":"funny-53","prompt":"Money can buy help, but what part of care is hardest to purchase?","theme":"Care, Family & Everyday Support","answers":["Attention","Trust","Time","Understanding"],"sort_order":53,"version":"funny"},{"id":"funny-54","prompt":"Someone clearly needs help but keeps saying ''I’m fine.'' Why?","theme":"Care, Family & Everyday Support","answers":["Pride","Fear of burdening others","Lack of trust","Habit of doing everything alone"],"sort_order":54,"version":"funny"},{"id":"funny-55","prompt":"When does ''I’m taking care of you'' start sounding suspiciously like ''I’m in charge of you''?","theme":"Care, Family & Everyday Support","answers":["One person decides everything","One person controls the money","One person has all the information","One person does all the work"],"sort_order":55,"version":"funny"},{"id":"funny-56","prompt":"If society gave care work a promotion, what would change first?","theme":"Care, Family & Everyday Support","answers":["Better pay","More time off","Stronger public services","More shared responsibility"],"sort_order":56,"version":"funny"},{"id":"funny-57","prompt":"What makes home feel like a place to recover instead of another shift?","theme":"Care, Family & Everyday Support","answers":["Privacy","Safety","Calm","Cooperation"],"sort_order":57,"version":"funny"},{"id":"funny-58","prompt":"What surprising life lesson does caring for someone teach fastest?","theme":"Care, Family & Everyday Support","answers":["Patience","Interdependence","Attention","Responsibility"],"sort_order":58,"version":"funny"},{"id":"funny-59","prompt":"Which kind of care does the worst job of showing up on a spreadsheet?","theme":"Care, Family & Everyday Support","answers":["Emotional care","Preventive care","Background planning","Companionship"],"sort_order":59,"version":"funny"},{"id":"funny-60","prompt":"When does community care stop being an idea and become very real?","theme":"Care, Family & Everyday Support","answers":["During illness","During a crisis","During childcare","During everyday routines"],"sort_order":60,"version":"funny"},{"id":"funny-61","prompt":"Your identity is a group project. Who keeps editing the document?","theme":"Identity, Roles & Social Expectations","answers":["Relationships","Work or school","Culture","Personal choices"],"sort_order":61,"version":"funny"},{"id":"funny-62","prompt":"When does a social role feel less like a role and more like a costume you’re not allowed to remove?","theme":"Identity, Roles & Social Expectations","answers":["There is no real alternative","Refusal brings punishment","Judgment is constant","Dependence makes leaving hard"],"sort_order":62,"version":"funny"},{"id":"funny-63","prompt":"What usually makes someone update their personal definition of ''me''?","theme":"Identity, Roles & Social Expectations","answers":["New relationships","New responsibilities","New ideas","New environments"],"sort_order":63,"version":"funny"},{"id":"funny-64","prompt":"When does a label become useful instead of just another box?","theme":"Identity, Roles & Social Expectations","answers":["It builds solidarity","It explains an experience","It gives people language","It creates visibility"],"sort_order":64,"version":"funny"},{"id":"funny-65","prompt":"When does a label go from helpful shortcut to tiny prison?","theme":"Identity, Roles & Social Expectations","answers":["It fixes expectations","It hides differences","It replaces curiosity","It becomes a stereotype"],"sort_order":65,"version":"funny"},{"id":"funny-66","prompt":"Someone wants to reinvent themselves. What do they need more than a motivational quote?","theme":"Identity, Roles & Social Expectations","answers":["Freedom","Community","Resources","Time"],"sort_order":66,"version":"funny"},{"id":"funny-67","prompt":"What creates the biggest ''That is NOT me'' reaction to a role people expect?","theme":"Identity, Roles & Social Expectations","answers":["Expected behavior","Expected duties","Expected appearance","Expected attitude"],"sort_order":67,"version":"funny"},{"id":"funny-68","prompt":"Where do social rules have the loudest indoor voice?","theme":"Identity, Roles & Social Expectations","answers":["Family","School","Workplace","Media"],"sort_order":68,"version":"funny"},{"id":"funny-69","prompt":"When does a shared identity become powerful enough to organize around?","theme":"Identity, Roles & Social Expectations","answers":["A common need","A common harm","A common goal","Mutual support"],"sort_order":69,"version":"funny"},{"id":"funny-70","prompt":"What keeps identity from turning into something carved in stone?","theme":"Identity, Roles & Social Expectations","answers":["Curiosity","Choice","Dialogue","Changing circumstances"],"sort_order":70,"version":"funny"},{"id":"funny-71","prompt":"What controls behavior while pretending it’s ''just your choice''?","theme":"Identity, Roles & Social Expectations","answers":["Rewards","Punishments","Habits","The need to belong"],"sort_order":71,"version":"funny"},{"id":"funny-72","prompt":"What makes someone finally push back against a role they were handed?","theme":"Identity, Roles & Social Expectations","answers":["It feels unfair","It does not fit them","It feels restrictive","It reduces dignity"],"sort_order":72,"version":"funny"},{"id":"funny-73","prompt":"What’s the hidden bill for ignoring society’s expectations?","theme":"Identity, Roles & Social Expectations","answers":["Financial cost","Social conflict","Uncertainty","Loneliness"],"sort_order":73,"version":"funny"},{"id":"funny-74","prompt":"When does someone feel most like the author of their own identity?","theme":"Identity, Roles & Social Expectations","answers":["When it is chosen","When it is supported","When it is lived consistently","When it can still change"],"sort_order":74,"version":"funny"},{"id":"funny-75","prompt":"How do people learn the rules nobody remembers agreeing to?","theme":"Identity, Roles & Social Expectations","answers":["By observing others","By being corrected","By being rewarded","By repetition"],"sort_order":75,"version":"funny"},{"id":"funny-76","prompt":"A big social label walks into the room. What important difference might it hide?","theme":"Identity, Roles & Social Expectations","answers":["Class differences","Cultural differences","Personal history","Power differences"],"sort_order":76,"version":"funny"},{"id":"funny-77","prompt":"What keeps solidarity from falling apart when everyone’s experiences differ?","theme":"Identity, Roles & Social Expectations","answers":["Listening","Shared goals","Mutual respect","Practical support"],"sort_order":77,"version":"funny"},{"id":"funny-78","prompt":"What changes a social role so much that grandparents and grandkids barely recognize it?","theme":"Identity, Roles & Social Expectations","answers":["Laws","Work patterns","Social movements","Technology"],"sort_order":78,"version":"funny"},{"id":"funny-79","prompt":"What’s a powerful way to break a stereotype without giving a lecture?","theme":"Identity, Roles & Social Expectations","answers":["Live differently","Speak openly","Organize together","Change institutions"],"sort_order":79,"version":"funny"},{"id":"funny-80","prompt":"What causes the classic identity dilemma: ''I belong here, but I’m still me''?","theme":"Identity, Roles & Social Expectations","answers":["Uniqueness","Belonging","Representation","Responsibility"],"sort_order":80,"version":"funny"},{"id":"funny-81","prompt":"A shiny new technology promises freedom. What would make you believe it?","theme":"Medicine, Technology & Body Change","answers":["The user controls it","The risks are clear","Access is fair","The benefit is meaningful"],"sort_order":81,"version":"funny"},{"id":"funny-82","prompt":"What makes medical advice feel less like an order and more like trustworthy guidance?","theme":"Medicine, Technology & Body Change","answers":["Options are explained","Consent is respected","Uncertainty is admitted","The person is listened to"],"sort_order":82,"version":"funny"},{"id":"funny-83","prompt":"Someone wants to change something about their body. What’s most likely influencing the decision?","theme":"Medicine, Technology & Body Change","answers":["Personal desire","Social pressure","A health need","Available technology"],"sort_order":83,"version":"funny"},{"id":"funny-84","prompt":"What makes people side-eye a new body-related technology?","theme":"Medicine, Technology & Body Change","answers":["Privacy","Inequality","Dependence","Unknown effects"],"sort_order":84,"version":"funny"},{"id":"funny-85","prompt":"Why would someone sign up for a human upgrade?","theme":"Medicine, Technology & Body Change","answers":["Convenience","Capability","Confidence","Opportunity"],"sort_order":85,"version":"funny"},{"id":"funny-86","prompt":"When does a helpful gadget start acting like a tiny digital boss?","theme":"Medicine, Technology & Body Change","answers":["Use becomes mandatory","Tracking becomes constant","Access is unequal","There is no real opt-out"],"sort_order":86,"version":"funny"},{"id":"funny-87","prompt":"A ''personal medical choice'' has four people hiding behind the curtain. Name one influence.","theme":"Medicine, Technology & Body Change","answers":["Cost shapes it","Social norms shape it","Work expectations shape it","Expert authority shapes it"],"sort_order":87,"version":"funny"},{"id":"funny-88","prompt":"Before shouting ''The future is here!'', what should we check first?","theme":"Medicine, Technology & Body Change","answers":["Safety","Consent","Fair access","Public discussion"],"sort_order":88,"version":"funny"},{"id":"funny-89","prompt":"A technology removes a human limit. What question should immediately ruin the launch party?","theme":"Medicine, Technology & Body Change","answers":["Who controls it?","Who benefits?","Who pays?","Who gets excluded?"],"sort_order":89,"version":"funny"},{"id":"funny-90","prompt":"Your health app wants your trust. What should it protect first?","theme":"Medicine, Technology & Body Change","answers":["Autonomy","Privacy","Access","Informed consent"],"sort_order":90,"version":"funny"},{"id":"funny-91","prompt":"When does ''self-improvement'' start feeling suspiciously like homework from society?","theme":"Medicine, Technology & Body Change","answers":["When comparison is constant","When jobs expect it","When trends demand it","When experts normalize it"],"sort_order":91,"version":"funny"},{"id":"funny-92","prompt":"What’s a sign wellness has gone from helpful to another full-time job?","theme":"Medicine, Technology & Body Change","answers":["Feeling guilty for resting","Tracking everything","Feeling pressure to spend","Fear of falling behind"],"sort_order":92,"version":"funny"},{"id":"funny-93","prompt":"Future upgrades are amazing—but how could they create a new VIP section of humanity?","theme":"Medicine, Technology & Body Change","answers":["High cost","Unequal access","Unequal education","Unequal infrastructure"],"sort_order":93,"version":"funny"},{"id":"funny-94","prompt":"Which human ability should never have to justify itself with a performance chart?","theme":"Medicine, Technology & Body Change","answers":["Speed","Output","Endurance","Efficiency"],"sort_order":94,"version":"funny"},{"id":"funny-95","prompt":"What makes an expert sound less like a guide and more like the final boss?","theme":"Medicine, Technology & Body Change","answers":["Alternatives are hidden","Questions are dismissed","Consent is rushed","Results are overpromised"],"sort_order":95,"version":"funny"},{"id":"funny-96","prompt":"When does technology become almost impossible to refuse?","theme":"Medicine, Technology & Body Change","answers":["Basic services require it","Social life requires it","Work requires it","Access systems require it"],"sort_order":96,"version":"funny"},{"id":"funny-97","prompt":"Your body data has a front door. Who should hold the main key?","theme":"Medicine, Technology & Body Change","answers":["The person","Their care team","A public health system","A research community"],"sort_order":97,"version":"funny"},{"id":"funny-98","prompt":"A device makes you better at work but knows everything about you. What are you protecting first?","theme":"Medicine, Technology & Body Change","answers":["Privacy","Convenience","Job security","Better performance"],"sort_order":98,"version":"funny"},{"id":"funny-99","prompt":"Before installing Human 2.0, what question belongs on the warning screen?","theme":"Medicine, Technology & Body Change","answers":["Necessary for whom?","Chosen by whom?","Paid for by whom?","Controlled by whom?"],"sort_order":99,"version":"funny"},{"id":"funny-100","prompt":"What’s the healthiest attitude toward a technology that promises to change everything?","theme":"Medicine, Technology & Body Change","answers":["Curiosity","Caution","Democratic debate","Informed choice"],"sort_order":100,"version":"funny"}]'::jsonb) r;